import { buildSecurityHeaders } from '@fodt/security-headers';

buildSecurityHeaders({
  csp: "default-src 'self'\nobject-src 'none'",
  hsts: { maxAge: 31536000, includeSubDomains: true, preload: false },
  nosniff: true,
});

import { gradeCsp } from '@fodt/security-headers';

// Each finding names its rule, severity, directive, finding, why, fix and basis.
gradeCsp("script-src 'unsafe-inline'").findings;
